import csv,sqlite3,collections
c=sqlite3.connect("file:/Users/jbotts/frus-analysis/c3/frus-copy-2026-10-25.db?mode=ro",uri=True)
c.execute("CREATE TEMP TABLE sc(volume_id TEXT, document_id TEXT, date TEXT)")
c.executemany("INSERT INTO sc VALUES(?,?,?)",[(r["volume_id"],r["document_id"],r["date"]) for r in csv.DictReader(open("scope.csv"))])
print("came-from, decimal_class, scope docs with citation_era='decimal', date<1958")
for r in c.execute("SELECT ds.decimal_class, COUNT(*) FROM sc s JOIN document_sources ds ON ds.volume_id=s.volume_id AND ds.document_id=s.document_id WHERE ds.citation_era='decimal' AND s.date<'1958' GROUP BY 1 ORDER BY 2 DESC LIMIT 8"): print("  ",r)
print("came-from, lot files (scope, date>=1940)")
for r in c.execute("SELECT ds.lot_file_norm, ds.series_name, COUNT(*) FROM sc s JOIN document_sources ds ON ds.volume_id=s.volume_id AND ds.document_id=s.document_id WHERE ds.citation_era='lot_file' AND s.date>='1940' GROUP BY 1,2 ORDER BY 3 DESC LIMIT 14"): print("  ",r)
print("came-from, structured collections (scope)")
for r in c.execute("SELECT ds.repository, ds.series_name, COUNT(*) FROM sc s JOIN document_sources ds ON ds.volume_id=s.volume_id AND ds.document_id=s.document_id WHERE ds.citation_era='structured' GROUP BY 1,2 ORDER BY 3 DESC LIMIT 14"): print("  ",r)
print("pointed-at, lot files (scope)")
for r in c.execute("SELECT ec.lot_file_norm, COUNT(*), COUNT(DISTINCT s.volume_id||'/'||s.document_id) FROM sc s JOIN external_citations ec ON ec.volume_id=s.volume_id AND ec.document_id=s.document_id WHERE ec.anchor='lotFile' GROUP BY 1 ORDER BY 2 DESC LIMIT 12"): print("  ",r)
print("pointed-at, presidential libraries (scope)")
for r in c.execute("SELECT ec.repository, ec.collection, COUNT(*) FROM sc s JOIN external_citations ec ON ec.volume_id=s.volume_id AND ec.document_id=s.document_id WHERE ec.anchor='presidentialLibrary' GROUP BY 1,2 ORDER BY 3 DESC LIMIT 10"): print("  ",r)
print("totals: scope docs with >=1 external citation row")
print(c.execute("SELECT COUNT(DISTINCT s.volume_id||'/'||s.document_id) FROM sc s JOIN external_citations ec ON ec.volume_id=s.volume_id AND ec.document_id=s.document_id").fetchone())
